def find_exploder_player(K, N, outcomes):
    current_player = K - 1  # Convert to zero-based index
    for T, Z in outcomes:
        if Z == 'T':
            current_player = (current_player + 1) % 8
        elif Z == 'N':
            pass  # Stay with the same player
        elif Z == 'P':
            pass  # Stay with the same player
    return current_player + 1  # Convert back to one-based index

if __name__ == "__main__":
    import sys
    input = sys.stdin.read
    data = input().split()

    K = int(data[0])
    N = int(data[1])
    outcomes = [(int(data[i]), data[i+1]) for i in range(2, 2 + 2*N, 2)]

    result = find_exploder_player(K, N, outcomes)
    print(result)
